/* presets.h — the patches of patches/NAME.json as a constant table (presets_gen.c, generated by
 * host/board_presets at every host build). Compiled into both cores: the M4 shows the names, the M7 applies
 * the values. Applying a preset: synth_init, synth_set_engine(engine_id), then synth_set_param for each of
 * its parameters (the host's patch_apply), so the board plays the patch like the WAV renders. */
#ifndef PRESETS_H
#define PRESETS_H

#include <stdint.h>

typedef struct {
    uint16_t id; /* synth_set_param id: engine parameter, or global (SYNTH_PARAM_GLOBAL..) */
    float value; /* normalized 0..1 */
} preset_param_t;

typedef struct {
    const char *name;
    const char *engine;      /* engine name ("mono", "fm6"...) */
    const char *description;
    uint8_t engine_id;       /* synth_engine_t */
    uint16_t first, count;   /* its slice of preset_params */
} preset_t;

extern const preset_param_t preset_params[];
extern const preset_t presets[];
extern const int preset_count;
/* catalog_hash() of the build that generated the table (host/catalog.h): the parameter ids it uses */
extern const uint32_t preset_catalog;

#endif /* PRESETS_H */
